class Solution {
    public int maxProfit(int[] prices) {
        int maxProfit = 0;              // 赚不到钱就返回 0，不能是负数
        int n = prices.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {   // j 必须大于 i，先买后卖
                int profit = prices[j] - prices[i];
                if (profit > maxProfit) {
                    maxProfit = profit;
                }
            }
        }
        return maxProfit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        if (n < 2) return 0;

        // suffixMax[i] 表示第 i 天到末尾的最高价
        int[] suffixMax = new int[n];
        suffixMax[n - 1] = prices[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixMax[i] = Math.max(prices[i], suffixMax[i + 1]);
        }

        int maxProfit = 0;
        for (int i = 0; i < n - 1; i++) {
            int profit = suffixMax[i + 1] - prices[i];
            if (profit > maxProfit) maxProfit = profit;
        }
        return maxProfit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE;   // 历史最低价
        int maxProfit = 0;                  // 历史最大利润

        for (int p : prices) {
            // 先算：假设今天卖出，用历史最低价买入能赚多少
            if (p - minPrice > maxProfit) {
                maxProfit = p - minPrice;
            }
            // 再更新历史最低价，保证它来自今天或更早
            if (p < minPrice) {
                minPrice = p;
            }
        }
        return maxProfit;
    }
}
